describe('Search Results Sorting', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should sort search results by relevance by default', () => {
    cy.get('[data-testid="sort-dropdown"]').should('have.value', 'relevance');
    cy.get('[data-testid="result-item"]').first().should('contain', 'Most Relevant');
  });

  it('should sort search results by price when selected', () => {
    cy.get('[data-testid="sort-dropdown"]').select('price');
    cy.get('[data-testid="sort-dropdown"]').should('have.value', 'price');

    cy.get('[data-testid="result-item"]').then(($items) => {
      const prices = [];
      $items.each((index, item) => {
        const price = parseFloat(cy.wrap(item).find('[data-testid="price"]').text().replace('$', ''));
        prices.push(price);
      });

      const sortedPrices = [...prices].sort((a, b) => a - b);
      expect(prices).to.deep.equal(sortedPrices);
    });
  });

  it('should sort search results by date when selected', () => {
    cy.get('[data-testid="sort-dropdown"]').select('date');
    cy.get('[data-testid="sort-dropdown"]').should('have.value', 'date');

    cy.get('[data-testid="result-item"]').first().should('be.visible');
    cy.get('[data-testid="result-date"]').first().should('contain', 'Posted');
  });

  it('should maintain sort order when navigating between pages', () => {
    cy.get('[data-testid="sort-dropdown"]').select('price');
    cy.get('[data-testid="next-page-button"]').click();
    cy.get('[data-testid="sort-dropdown"]').should('have.value', 'price');
  });

  it('should handle empty search results with sort options available', () => {
    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-input"]').type('xyznonexistentproduct12345');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="sort-dropdown"]').should('be.disabled');
  });
});
